'use strict';
const $=id=>document.getElementById(id);
const names=['一萬','二萬','三萬','四萬','五萬','六萬','七萬','八萬','九萬','一筒','二筒','三筒','四筒','五筒','六筒','七筒','八筒','九筒','一索','二索','三索','四索','五索','六索','七索','八索','九索','東','南','西','北','白','發','中'];
let state,selected=-1,riichiPick=false,timers=[],sound=false,ctx,round=0;
function later(fn,ms){timers.push(setTimeout(fn,ms))}
function tone(freq=450){if(!sound)return;try{ctx??=new (window.AudioContext||window.webkitAudioContext)();const o=ctx.createOscillator(),g=ctx.createGain();o.type='triangle';o.frequency.value=freq;o.connect(g);g.connect(ctx.destination);g.gain.setValueAtTime(.045,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.13);o.start();o.stop(ctx.currentTime+.14)}catch{}}
function counts(hand){const c=Array(34).fill(0);for(const t of hand)c[t]++;return c}
function groups(c){const i=c.findIndex(x=>x>0);if(i<0)return true;if(c[i]>=3){c[i]-=3;const ok=groups(c);c[i]+=3;if(ok)return true}if(i<27&&i%9<7&&c[i+1]&&c[i+2]){c[i]--;c[i+1]--;c[i+2]--;const ok=groups(c);c[i]++;c[i+1]++;c[i+2]++;if(ok)return true}return false}
function winning(hand){if(hand.length!==14)return false;let c=counts(hand);if(c.filter(n=>n===2).length===7)return true;const ends=[0,8,9,17,18,26,27,28,29,30,31,32,33];if(ends.every(i=>c[i]>0)&&ends.some(i=>c[i]>1))return true;for(let i=0;i<34;i++)if(c[i]>=2){c[i]-=2;const ok=groups(c);c[i]+=2;if(ok)return true}return false}
function waits(hand){if(hand.length!==13)return [];const c=counts(hand),out=[];for(let i=0;i<34;i++)if(c[i]<4&&winning([...hand,i]))out.push(i);return out}
function riichiOptions(){return state.hands[0].map((t,i)=>waits(state.hands[0].filter((_,j)=>i!==j)).length?i:-1).filter(i=>i>=0)}
function tile(t,small=false){const el=document.createElement('span');el.className='tile'+(small?' small':'');el.title=names[t];if(t<27){const suit=Math.floor(t/9);el.classList.add(['man','pin','sou'][suit]);el.innerHTML='<span class="num">'+(t%9+1)+'</span><span class="suit">'+['萬','筒','索'][suit]+'</span>'}else{el.classList.add('honor');if(t===32)el.classList.add('green');if(t===33)el.classList.add('red');el.textContent=names[t]}return el}
function render(){for(let p=0;p<4;p++){$('river'+p).replaceChildren(...state.rivers[p].map(t=>tile(t,true)))}$('wall').textContent=state.wall.length;$('round').textContent=round;$('dora').replaceChildren(tile(state.indicator,true));const h=$('hand');h.replaceChildren();state.hands[0].forEach((t,i)=>{const b=document.createElement('button'),v=tile(t);b.className=v.className+(i===selected?' selected':'');b.innerHTML=v.innerHTML;b.setAttribute('aria-label',names[t]+(i===state.hands[0].length-1?' 摸入':''));b.setAttribute('aria-pressed',i===selected);b.disabled=state.turn!==0||state.over||(state.riichi&&i!==state.hands[0].length-1);b.onclick=()=>{tone(540);if(selected===i)discard();else{selected=i;render()}};h.appendChild(b)});const active=state.turn===0&&!state.over;$('discard').disabled=!active||selected<0;$('win').disabled=!active||!winning(state.hands[0]);$('riichi').disabled=!active||state.riichi||state.wall.length<4||!riichiOptions().length;$('riichi').textContent=state.riichi?'已立直':riichiPick?'取消立直':'立直';$('tilelabel').textContent=selected>=0?names[state.hands[0][selected]]:'选择一张牌';$('status').textContent=state.over?'本局结束':state.turn===0?(state.riichi?'已立直 · 摸切或自摸':riichiPick?'选择听牌切牌':'轮到你出牌'):['','比利正在思考…','雅正在思考…','艾莲正在思考…'][state.turn];if(riichiPick){$('hint').textContent='可切：'+riichiOptions().map(i=>names[state.hands[0][i]]).filter((v,i,a)=>a.indexOf(v)===i).join('、')}else if(state.riichi){$('hint').textContent='等待：'+state.waiting.map(i=>names[i]).join('、')}else{$('hint').textContent='点击选择，再次点击或按“切牌”确认'}}
function newGame(){timers.forEach(clearTimeout);timers=[];clearEffects();$('cutin').hidden=true;if($('modal').open)$('modal').close();const wall=Array.from({length:136},(_,i)=>Math.floor(i/4));for(let i=wall.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[wall[i],wall[j]]=[wall[j],wall[i]]}const dead=wall.splice(-14);state={wall,hands:[[],[],[],[]],rivers:[[],[],[],[]],indicator:dead[4],dead,turn:0,over:false,riichi:false,waiting:[]};for(let p=0;p<4;p++){state.hands[p]=wall.splice(-13).sort((a,b)=>a-b)}state.hands[0].push(wall.pop());round++;selected=-1;riichiPick=false;$('quote').textContent='好啦，这一局就交给你了。';render()}
let actionEffects=[];
function clearEffects(){for(const fx of actionEffects)fx.remove();actionEffects=[];document.querySelectorAll?.(".character-sprite").forEach(p=>p.classList.remove("discarding"));}
function animateDiscard(player){
 if(document.body.classList.contains('no-motion')||matchMedia('(prefers-reduced-motion: reduce)').matches)return;
 const target=$('river'+player).lastElementChild;
 if(!target?.animate)return;
 const board=document.querySelector('.world'),rect=board.getBoundingClientRect(),tr=target.getBoundingClientRect(),scale=rect.width/1000,br={width:1000,height:2000/3};
 const x=(tr.left+tr.width/2-rect.left)/scale,y=(tr.top+tr.height/2-rect.top)/scale;
 const origins=[[550,470],[800,280],[450,197],[200,385]];
 const [sx,sy]=origins[player];
 const person=board.querySelector?.('.person-'+player+' .character-sprite');
 if(person){person.classList.remove('discarding');void person.offsetWidth;person.classList.add('discarding');later(()=>person.classList.remove('discarding'),1200)}
 target.animate([{opacity:0},{opacity:0,offset:.99},{opacity:1}],{duration:650});
 const fly=target.cloneNode(true);fly.className+=' flying-tile';fly.style.opacity='0';board.appendChild(fly);actionEffects.push(fly);
 fly.animate([{transform:`translate(${sx}px,${sy}px) translate(-50%,-50%) rotate(-22deg) scale(2.2)`,opacity:1},{transform:`translate(${x}px,${y}px) translate(-50%,-50%) rotate(0deg) scale(1)`,opacity:1}],{duration:250,delay:400,easing:'cubic-bezier(.16,.8,.28,1)',fill:'forwards'});
 const burst=document.createElement('img');burst.src='impact.png';burst.className='impact-art';burst.alt='';burst.style.left=x+'px';burst.style.top=y+'px';board.appendChild(burst);actionEffects.push(burst);
 burst.animate([{opacity:0,transform:'translate(-50%,-50%) scale(.15)'},{opacity:0,transform:'translate(-50%,-50%) scale(.15)',offset:.54},{opacity:.95,transform:'translate(-50%,-50%) scale(.65)',offset:.56},{opacity:0,transform:'translate(-50%,-50%) scale(1.25)'}],{duration:1200,fill:'forwards'});
 const banner=document.createElement('div');banner.className='discard-banner '+(player===0?'nicole-banner':'opponent-banner');
 const label=document.createElement('b');label.textContent=['妮可','比利','雅','艾莲'][player]+' / 切';banner.appendChild(label);
 const name=document.createElement('span');name.textContent=names[state.rivers[player].at(-1)];banner.appendChild(name);board.appendChild(banner);actionEffects.push(banner);
 banner.animate([{opacity:0,transform:'translateX(-110%) skewX(-7deg)'},{opacity:1,transform:'translateX(0) skewX(-7deg)',offset:.2},{opacity:1,transform:'translateX(0) skewX(-7deg)',offset:.7},{opacity:0,transform:'translateX(30%) skewX(-7deg)'}],{duration:900,fill:'forwards'});
 const surface=board.querySelector?.('.table-layer')||board;surface.animate([{transform:'translate(0,0)'},{transform:'translate(2px,1px)'},{transform:'translate(-2px,0)'},{transform:'translate(0,0)'}],{duration:150,delay:650});
 later(()=>{fly.remove();tone(190)},650);
 later(()=>{for(const el of [fly,burst,banner])el.remove();actionEffects=actionEffects.filter(el=>![fly,burst,banner].includes(el))},1230);
}
function cutin(title='RIICHI!',sub='立 直'){if(document.body.classList.contains('no-motion')||matchMedia('(prefers-reduced-motion: reduce)').matches)return;$('cut-title').textContent=title;$('cut-sub').textContent=sub;$('cutin').hidden=false;tone(700);later(()=>$('cutin').hidden=true,1800)}
function show(html){$('modalbody').innerHTML=html;$('modal').showModal()}
function finish(winner){state.over=true;render();if(winner>=0){if(winner===0)cutin('TSUMO!','自 摸');const who=['妮可 · 你','比利','雅','艾莲'][winner];$('quote').textContent=winner===0?'这笔收入，我就收下啦。':'别急，下一局赢回来。';later(()=>{show('<h2>'+who+' 自摸</h2><div id="result-hand" style="display:flex;gap:3px;flex-wrap:wrap"></div><p>门前清自摸和'+(winner===0&&state.riichi?' · 立直':'')+'</p><p>练习局只验证和牌牌形，不结算符数、番数或点数。</p><button id="next" class="primary">再来一局 ↗</button>');$('result-hand').replaceChildren(...state.hands[winner].map(t=>tile(t,true)));$('next').onclick=newGame},winner===0?1800:200)}else{show('<h2>荒牌流局</h2><p>牌山已摸完。'+(waits(state.hands[0]).length?'你已听牌。':'这一局尚未听牌。')+'</p><button id="next" class="primary">再来一局 ↗</button>');$('next').onclick=newGame}}
function discard(){if(state.over||state.turn!==0||selected<0)return;if(state.riichi&&selected!==state.hands[0].length-1)return;if(riichiPick&&!riichiOptions().includes(selected)){ $('hint').textContent='这张牌切出后无法听牌，请选择提示中的牌。';return}state.rivers[0].push(state.hands[0].splice(selected,1)[0]);state.hands[0].sort((a,b)=>a-b);if(riichiPick){state.riichi=true;state.waiting=waits(state.hands[0]);riichiPick=false;cutin();$('quote').textContent='筹码押上了，可别让我失望。'}selected=-1;tone(280);state.turn=1;render();animateDiscard(0);later(bot,1300)}
function botChoice(hand){let best=-Infinity,choice=0;for(let i=0;i<hand.length;i++){const kept=hand.filter((_,j)=>j!==i),c=counts(kept);let score=waits(kept).length*50;for(let t=0;t<34;t++){score+=c[t]>=3?10:c[t]===2?5:0;if(t<27){if(t%9<8)score+=Math.min(c[t],c[t+1])*2;if(t%9<7)score+=Math.min(c[t],c[t+2])}}if(score>best){best=score;choice=i}}return choice}
function bot(){if(state.over)return;if(!state.wall.length){finish(-1);return}const p=state.turn;state.hands[p].push(state.wall.pop());if(winning(state.hands[p])){finish(p);return}const i=botChoice(state.hands[p]);state.rivers[p].push(state.hands[p].splice(i,1)[0]);state.turn=(p+1)%4;if(state.turn===0){if(!state.wall.length){finish(-1);return}state.hands[0].push(state.wall.pop());selected=state.riichi?state.hands[0].length-1:-1;render();animateDiscard(p);tone(500)}else{render();animateDiscard(p);later(bot,1300)}}
$('scene').onclick=()=>{const roof=document.body.classList.toggle('rooftop');$('scene').textContent='光线：'+(roof?'日光':'夜场')+' ↻'};
$('discard').onclick=discard;$('new').onclick=()=>show('<h2>重新发牌？</h2><p>当前练习局将结束。</p><button class="primary" id="reset">重新开始</button>');document.addEventListener('click',e=>{if(e.target.id==='reset')newGame()});$('win').onclick=()=>{if(state.turn===0&&!state.over&&winning(state.hands[0]))finish(0)};$('riichi').onclick=()=>{riichiPick=!riichiPick;render()};$('close').onclick=()=>$('modal').close();$('sound').onclick=()=>{sound=!sound;$('sound').textContent='声音 '+(sound?'ON':'OFF');$('sound').setAttribute('aria-pressed',sound);tone()};$('motion').onclick=()=>{const off=document.body.classList.toggle('no-motion');$('motion').textContent='动作特效 '+(off?'OFF':'ON');$('motion').setAttribute('aria-pressed',!off);if(off){$('cutin').hidden=true;clearEffects()}};$('rules').onclick=()=>show('<h2>妮可的门前练习桌</h2><p>与三个电脑轮流摸牌、切牌。凑齐四组面子与一对雀头，也支持七对子、国士无双。</p><ul><li>点击手牌选中，再点一次或按“切牌”。</li><li>切牌后能听牌时，可选择“立直”。立直后只能摸切或自摸。</li><li>满足和牌牌形时，“自摸”按钮会亮起。</li></ul><p>此版为动态美术与门前摸切原型：无吃碰杠、荣和、符番计分、赤宝牌与东风战进程。宝牌指示仅作展示。电脑仅使用自身手牌决策。</p><p>每次切牌都有飞牌、落桌冲击与短分镜；立直、自摸播放更大的角色演出。四名角色各用独立的六帧出牌序列：准备、伸手、放牌、跟随、收手、归位。飞牌与落桌特效由独立图层同步播放。非官方同人作品。</p>');document.addEventListener('keydown',e=>{if($('modal').open||state.over||state.turn!==0)return;if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();selected=state.riichi?13:(selected+(e.key==='ArrowRight'?1:-1)+14)%14;render()}if(e.key==='Enter'&&document.activeElement.tagName!=='BUTTON')discard()});
newGame();
if(typeof ResizeObserver!=='undefined'){
 const viewport=document.querySelector('.board'),world=document.querySelector('.world');
 const resize=()=>world.style.setProperty('--scene-scale',viewport.clientWidth/1000);
 new ResizeObserver(resize).observe(viewport);resize();
}
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_mahjong_table',description:'Read the visible player hand, rivers and turn, without revealing opponents hands or the hidden wall.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({hand:state.hands[0].map(t=>names[t]),rivers:state.rivers.map(r=>r.map(t=>names[t])),remaining:state.wall.length,turn:state.turn,over:state.over})})).catch(()=>{})}catch{}}
